import json

if isinstance(documents, dict):
    shape = [
        {
            "document_key": key,
            "value_type": type(value).__name__,
            "top_level_keys": json.dumps(sorted(value.keys()), ensure_ascii=False) if isinstance(value, dict) else "",
        }
        for key, value in documents.items()
    ]
