result = shape

import re

rows = []

search_docs = [
    doc for doc in documents.values()
    if isinstance(doc.get("structuredContent"), dict)
    and isinstance(doc["structuredContent"].get("items"), list)
]
if len(search_docs) != 1:
    raise ValueError("未唯一识别检索结果文档")
for item in search_docs[0]["structuredContent"]["items"]:
    rows.append({
        "来源": "检索结果",
        "标题": item["name"],
        "id": item["id"],
    })

detail_docs = [
    doc for doc in documents.values()
    if isinstance(doc.get("content"), list)
    and doc.get("structuredContent") is None
]
if len(detail_docs) != 1:
    raise ValueError("未唯一识别详情结果文档")
detail_text = "\n".join(
    part["text"] for part in detail_docs[0]["content"] if part.get("type") == "text"
)
title_match = re.search(r"^\s*#\s+(.+?)\s*$", detail_text, re.MULTILINE)
id_match = re.search(r"模板\s*id\s*[:：]\s*([^\s]+)", detail_text)
if not title_match or not id_match:
    raise ValueError("详情输出中未找到标题或 id")
rows.append({
    "来源": "详情结果",
    "标题": title_match.group(1),
    "id": id_match.group(1),
})

result = rows

